api_mappings.custom_func_imp:
cudnnStatus_t cudnnGetProperty(libraryPropertyType type, int * value) {
    // TraceCall("cudnnGetProperty");
    if(type == MAJOR_VERSION) {
        *value = CUDNN_MAJOR;
    } else if (type == MINOR_VERSION) {
        *value = CUDNN_MINOR;
    } else if (type == PATCH_LEVEL) {
        *value = CUDNN_PATCHLEVEL;
    } else {
        printf("Unknown library property type: %d\n", type);
        exit(1);
    }
    return CUDNN_STATUS_SUCCESS;
}

global_custom_code.pre_wrapper_call:
bool needProfile = g_profileHandler.isCallbackEnabled != NULL &&
    g_profileHandler.isCallbackEnabled(g_profileDomain, cudnn_TRACE_CBID_$WRAPPER_FUNC_NAME) != 0;
if (needProfile) {
    g_profileHandler.profileCallbackBegin(g_profileDomain, cudnn_TRACE_CBID_$WRAPPER_FUNC_NAME);
}
